INSERT INTO `pengumpulan_tugas` (`id`, `tugas_id`, `siswa_id`, `tugas_kelompok_id`, `file_jawaban`, `link_jawaban`, `catatan_siswa`, `nilai`, `catatan_guru`, `dikumpulkan_at`, `dinilai_at`, `created_at`, `updated_at`) VALUES
(1, 4, 1278, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/4', 'asdasdasda', NULL, NULL, '2026-09-23 00:38:52', NULL, '2026-09-23 00:38:52', '2026-09-23 00:38:52'),
(3, 6, 1255, NULL, NULL, 'http://lms.yasor-ms.my.id/lms/siswa/tugas/6', 'Kesalahan Rani :\r\nTidak menggunakan mouse\r\nLayar sejajar dada\r\nBekerja di kasur\r\nLampu dimatikan\r\nJam kerja berlebihan\r\nKurangnya manajemen istirahat\r\nSolusi untuk Rani:\r\nPertama membeli meja lipat lesehan untuk laptop yang bisa diatur tinggi nya dengan budget 120k. Lalu mouse dan keyboard eksternal 130k. Beli stand/sandaran laptop plastik ataupun alumunium 50k. Menggunakan lampu belajar 70k. Dan gunakan bantal sandaran', NULL, NULL, '2026-09-23 00:52:37', NULL, '2026-09-23 00:51:48', '2026-09-23 00:52:37'),
(4, 6, 1268, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/6', '1. laptop di taruh di atas kasur\r\n2. tidak menggunakan mouse\r\n3. laptopnya ga sejajar dengan mata\r\n4. posisi leher terlalu membungkuk\r\n5. lampu kamar nya dimatikan saat bekerja\r\n6. tidak ada penyangga punggung yang baik \r\nrancangan perbaikan : stand laptop - 100rb, mouse 75rb, keyboard eksternal 100rb, lampu meja 100rb, bantal penyangga punggung 75rb, dan meja kecil 50rb', NULL, NULL, '2026-09-23 00:52:35', NULL, '2026-09-23 00:52:35', '2026-09-23 00:52:35'),
(5, 6, 1266, NULL, NULL, 'https://kewerkewer.com', '6 kesalahan teknis Rani \r\n1. Bekerja di atas kasur\r\n2. Layar sejajar dengan dada\r\n3. Tanpa mouse \r\n4. Lampu kamar mati\r\n5. Tidak melakukan jeda mata atau istirahat bertahap\r\n6. Kasur dipakai untuk kerja dan tidur \r\nDengan budget 500.00\r\nMeja lipat portable untuk laptop\r\nMouse wireless murah\r\nLampu meja LED \r\nBantal sandaran punggung \r\nPilih yg murah dan nyaman sesuai budget lah', NULL, NULL, '2026-09-23 00:54:28', NULL, '2026-09-23 00:52:35', '2026-09-23 00:54:28'),
(6, 6, 1280, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/6', '6 kesalahan ergonomi:\r\n\r\n1. Laptop diletakkan di atas kasur\r\n\r\n\r\n2. Tidak menggunakan mouse\r\n\r\n\r\n3. Layar laptop tidak sejajar dengan mata\r\n\r\n\r\n4. Posisi leher terlalu membungkuk\r\n\r\n\r\n5. Lampu kamar dimatikan sehingga pencahayaan kurang\r\n\r\n\r\n6. Tidak ada penyangga punggung yang baik\r\n\r\n\r\n\r\nRancangan perbaikan: Stand laptop Rp100.000 Mouse Rp75.000 Keyboard eksternal Rp100.000 Lampu meja Rp100.000 Bantal penyangga punggung Rp75.000 Alas atau meja kecil Rp50.000\r\n\r\nTotal Rp500.000', NULL, NULL, '2026-09-23 00:53:24', NULL, '2026-09-23 00:53:24', '2026-09-23 00:53:24'),
(7, 6, 1258, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/6', '6 Kesalahan Ergonomisnya \r\n- duduk tanpa sandaran\r\n- layar tidak sejajar dengan pandangan \r\n- siku tidak 90°\r\n- posisi tubuh tidak tegak\r\n- pencahayaan kurang\r\n- tidak menggunakan alat proper seperti mouse, meja, kursi\r\n\r\nRancangan Ergonomis \r\nBila memang gamau pake kursi proper, bisa beli sanggahan punggung yg harganya 100kan, terus meja belajar kecil di harga 80kan, mouse yang sesuai standar kerja 100k, kacamata anti radiasi 100k, dan kursi bantal di harga 120k\r\n\r\nanggaran segitu udah oke banget buat menjaga ergonomis dan keselamatan tulang dari skoliosis selama kerja', NULL, NULL, '2026-09-23 00:55:09', NULL, '2026-09-23 00:54:09', '2026-09-23 00:55:09'),
(8, 6, 1264, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/6', 'Rani harus beli kursi yang bisa untuk bersandar, lalu memakai kacamata anti radiasi, menerapkan sistem 20-20-20, Rani harus pindah tempat kerja jangan di kasur soal nya kalau di kasur akan menyebabkan kasur panas dan tidak nyaman, Rani juga harus membeli mouse agar kerja lebih efektif, dan harus membeli lampu khusus belajar atau paling tidak nyalakan lampu saat ber aktifitas', NULL, NULL, '2026-09-23 00:54:09', NULL, '2026-09-23 00:54:09', '2026-09-23 00:54:09'),
(9, 6, 1253, NULL, NULL, 'https://lms.yasor-ms.my.id', '1.Bekerja di atas kasur: Membuat postur bungkuk dan merusak tulang belakang.  \r\n​2.Layar sejajar dada: Memaksa leher menunduk (sakit leher).  \r\n​3.Tanpa mouse (pakai touchpad): Bikin otot tangan dan pergelangan cepat lelah.\r\n​4.Lampu dimatikan: Kontras layar bikin mata perih dan lelah.  \r\n​5.Cahaya biru di ruang gelap: Mengganggu produksi melatonin (sulit tidur).  \r\n​6.Tidak ada jeda istirahat: Memicu kelelahan fisik dan mata menumpuk.', NULL, NULL, '2026-09-23 00:54:11', NULL, '2026-09-23 00:54:11', '2026-09-23 00:54:11'),
(10, 6, 1260, NULL, NULL, 'https://lms.yasor-ms.my.id', 'Kesalahan Rani:\r\nLaptop dipakai di atas kasur.\r\nTidak menggunakan mouse.\r\nLayar laptop terlalu rendah sehingga leher menunduk.\r\nBekerja di kamar yang gelap.\r\nDuduk terlalu lama tanpa istirahat.\r\nJarang melakukan peregangan.\r\nTerlalu lama melihat layar sehingga mata perih.\r\nMenggunakan laptop sampai mengganggu waktu tidur.\r\nPerbaikan dengan budget Rp500.000:\r\nStand laptop: Rp100.000\r\nMouse: Rp70.000\r\nKeyboard: Rp100.000\r\nLampu meja: Rp80.000\r\nBantal duduk: Rp80.000', NULL, NULL, '2026-09-23 00:56:50', NULL, '2026-09-23 00:54:54', '2026-09-23 00:56:50'),
(11, 6, 1278, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/6', 'Kesalahan yang rani lakukan adalah bekerja terlalu lama, posisi duduk tidak tegak, lampu kamar dimatikan, tidak memakai mouse, layar terlalu rendah dan laptop di atas kasur.\r\n\r\nyang harus rani lakukan adalah membeli mouse, memperbaiki posisi kerja, menggunakan alat ergonomis sederhana, mengatur pencahayaan, dan rutin beristirahat agar leher serta mata tidak cepat lelah.', NULL, NULL, '2026-09-23 00:54:55', NULL, '2026-09-23 00:54:55', '2026-09-23 00:54:55'),
(12, 6, 1273, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/6', 'kesalahan rani: tidak duduk tegak di kursi, layar tidak sejajar mata,  lampu dimatikan, laptop di atas kasur, tidak memakai mouse dan bekerja terlalu lama. \r\n\r\nmembeli mouse, meja, kursi, lampu', NULL, NULL, '2026-09-23 00:57:32', NULL, '2026-09-23 00:55:01', '2026-09-23 00:57:32'),
(13, 6, 1279, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/6', '1. Bekerja di atas kasur \r\n2. ga menggunakan meja dan kursi kerja \r\n3. ga menggunakan mouse \r\n4. Posisi layar sejajar dada \r\n5. Pencahayaan kamar terlalu gelap laptop terang\r\n6. posisi duduk bungkuk \r\n\r\nperbaikan budget Rp500.000\r\n\r\nMeja laptop 	Rp200.000\r\nMouse 	Rp75.000\r\nStand laptop	Rp100.000\r\nLampu meja	Rp70.000\r\nTotal	Rp445.000', NULL, NULL, '2026-09-23 00:55:01', NULL, '2026-09-23 00:55:01', '2026-09-23 00:55:01'),
(14, 5, 1291, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/5', '* Stand laptop: Rp100.000\r\n* Keyboard eksternal: Rp100.000\r\n* Mouse: Rp70.000\r\n* Lampu meja: Rp80.000\r\n* Bantal penyangga punggung: Rp75.000\r\n* Alas duduk: Rp50.000', NULL, NULL, '2026-09-23 00:56:24', NULL, '2026-09-23 00:55:04', '2026-09-23 00:56:24'),
(15, 6, 1274, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/6', '1. Bekerja pake laptop diatas kasur.\r\n2. Tidak pake mouse.\r\n3. Posisi layar sejajar dada.\r\n4. Cahaya kamar mati.\r\n5. Posisi duduk tidak ergonomis.\r\n6. Kurang istirahat dari layar.\r\n\r\nPerbaikan dgn anggaran 500ribu\r\n-beli stand laptop agar layar lebih tinggi(100 ribu)\r\n-mouse ergonomis/basic(75ribu)\r\n-keyboard eskternal(100rb)\r\n-lampu meja(75ribu)\r\n-bantal dudukan pinggang(75ribu)', NULL, NULL, '2026-09-23 00:55:28', NULL, '2026-09-23 00:55:28', '2026-09-23 00:55:28'),
(16, 5, 1285, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/5', 'Kesalahan Rani\r\nBekerja di atas kasur\r\nLayar terlalu rendah\r\nPosisi duduk membungkuk\r\nTidak memakai mouse\r\nKamar terlalu gelap\r\nJarang istirahat dari layar\r\nBekerja terlalu dekat dengan waktu tidur\r\n\r\nperbaikan\r\nstand laptop\r\nkeyboard eksternal \r\nmouse\r\nlampu meja\r\nbantal penyangga buat punggung\r\nalas duduk', NULL, NULL, '2026-09-23 00:55:34', NULL, '2026-09-23 00:55:34', '2026-09-23 00:55:34'),
(17, 5, 1283, NULL, NULL, 'https://lms.yasor-ms.my.id/', 'laptop di atas kasur - memakai meja laptop stand tidak menggunakan mouse - membeli mouse\r\nlayar sejajar dengan dada- menaikan layar hingga sejajar dengan mata\r\nposisi duduk tidak tegak- menggunakan korsi dengan sandaran\r\npercahayaan terlalu gelap- gunakan lampu meja\r\nporsi kerja terlalu lama- lakukan istirahat dan peregangan setiap 30-60 menit', NULL, NULL, '2026-09-23 00:56:49', NULL, '2026-09-23 00:56:30', '2026-09-23 00:56:49'),
(18, 6, 1275, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/6', '- Bekerja di atas kasur \r\n- Tidak menggunakan meja dan kursi kerja \r\n-Tidak menggunakan mouse \r\n-Posisi layar sejajar dada \r\n-Pencahayaan kamar terlalu gelap \r\n-Kemungkinan posisi duduk membungkuk \r\nRancangan perbaikan dengan budget maksimal Rp500.000\r\nKebutuhan Perkiraan biaya\r\nMeja laptop sederhana	Rp200.000\r\nMouse wireless Rp75.000\r\nStand laptop Rp100.000\r\nLampu meja/desk lamp	Rp75.000\r\nTotal Rp450.000', NULL, NULL, '2026-09-23 00:56:32', NULL, '2026-09-23 00:56:32', '2026-09-23 00:56:32'),
(19, 6, 1254, NULL, NULL, 'https://lms.yasor-ms.my.id/lms', '1.kerja pake laptop di atas kasur jadi,posisi kasur kurang nyaman dan kurang stabil\r\n\r\n2.laptop layar terlalu rendah,sejahar dada jadi leher sering menunduk \r\n3.ga pake mouse jadi tangan cepet pegal\r\n4.posisi duduk kurang tegak dan ga ada penyangga punggung \r\n5.lampu kamar di matiin jadi mata cepet cape \r\n6.duduk terlalu lama tanpa sering berdrii atau stretching\r\n\r\nperbaikan dengan budget maksimal Rp.500.000\r\n\r\nstand laptop:Rp.100.000\r\nkeyboard tambahan:Rp.100.000\r\nmouse:Rp.75.000\r\nlampu meja:Rp.75.000\r\nBantal penyangga punggung:Rp.100.000', NULL, NULL, '2026-09-23 01:00:39', NULL, '2026-09-23 00:56:47', '2026-09-23 01:00:39'),
(20, 6, 1281, NULL, NULL, 'https://lms-ms.my.id', '1.Bekerja di atas kasur: Membuat postur bungkuk dan merusak tulang belakang.  \r\n​2.Layar sejajar dada: Memaksa leher menunduk (sakit leher).  \r\n​3.Tanpa mouse (pakai touchpad): Bikin otot tangan dan pergelangan cepat lelah.\r\n​4.Lampu dimatikan: Kontras layar bikin mata perih dan lelah.  \r\n​5.Cahaya biru di ruang gelap: Mengganggu produksi melatonin (sulit tidur).  \r\n​6.Tidak ada jeda istirahat: Memicu kelelahan fisik dan mata menumpuk.', NULL, NULL, '2026-09-23 00:57:06', NULL, '2026-09-23 00:57:06', '2026-09-23 00:57:06'),
(21, 6, 1259, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/6', 'Kesalahan rani \r\n1. Laptop di letakan di kasur sehingga tidak stabil posisi kerja\r\n2. Tidak menggunakan meja dan kursi yang sesuai\r\n3. Posisi layar terlalu rendah karena sejajar dengan dada\r\n4. Posisi leher menjadi menunduk terlalu lama, menyebabkan sakit leher\r\n5. Bekerja dalam kondisi lampu mati\r\n6. Tidak memperhatikan posisi duduk dan postur tubuh\r\n\r\nRancangan perbaikan :\r\n1. Laptop stand Rp.100.000\r\n2. Lampu meja Rp.75.000\r\n3. Keybord + mouse Rp. 100.000\r\n4. Bantal / alas duduk ergonomis Rp. 75.000', NULL, NULL, '2026-09-23 00:57:19', NULL, '2026-09-23 00:57:19', '2026-09-23 00:57:19'),
(22, 5, 1284, NULL, NULL, 'https://lms.yasor-ms.my.id/', 'Kesalahan ergonomis:\r\nLaptop diletakkan di atas kasur.\r\nTidak menggunakan mouse.\r\nPosisi duduk dan layar tidak ergonomis.\r\nLampu kamar dimatikan saat bekerja.\r\nMenatap layar terlalu lama.\r\nKurang istirahat dan peregangan.\r\nRencana perbaikan (Rp500.000):\r\nMouse: Rp50.000\r\nStand laptop: Rp150.000\r\nLampu meja: Rp100.000\r\nKeyboard eksternal: Rp150.000\r\nSisa untuk istirahat/penunjang: Rp50.000\r\nSaran: Terapkan aturan 20-20-20 untuk mengurangi ketegangan mata dan perbaiki jadwal tidur', NULL, NULL, '2026-09-23 00:57:24', NULL, '2026-09-23 00:57:24', '2026-09-23 00:57:24'),
(23, 6, 1262, NULL, NULL, 'https://lms.yasor-ms.my.id/lms', 'Kesalahan Rani\r\n1. Kerja di kasur\r\n2. Layar kerendahan - sejajar dada\r\n3. Tanpa mouse\r\n4. Lampu mati\r\n5. No stretching / nonstop ngoding\r\n6. Kebanyakan blue light malem\r\n\r\nFix 500k\r\nMeja lipat 150k, stand laptop 70k, mouse 100k, lampu meja 120k, bantal punggung 50k. Total 490k.\r\n\r\nAtur layar sejajar mata + lampu nyala + istirahat 20-20-20.', NULL, NULL, '2026-09-23 00:57:45', NULL, '2026-09-23 00:57:40', '2026-09-23 00:57:45'),
(24, 6, 1257, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/6', 'bekerja diatas kasur\r\ntidak pake kursi dan meja\r\nlampu kamarnya dimatikan\r\nkurang tidur\r\nlayar terlalu dekat ga sejajar\r\nposisi kerjanya dikasur \r\n\r\nbeli kursi meja second 250rb\r\nbeli mouse 80rb\r\nbeli keyboard 100rb\r\nlampu belajar 50rb\r\nstand laptop biar sejajar 80rb', NULL, NULL, '2026-09-23 00:58:04', NULL, '2026-09-23 00:58:04', '2026-09-23 00:58:04'),
(25, 5, 1295, NULL, NULL, 'https://lms.yasor-ms.my.id/', 'bekerja di atas kasur \r\ntanpa menggunakan mouse\r\nlayar sejajar dengan dada\r\nlampu kamar di matikan \r\npaparan blue light sebelum tidur \r\nbekerja tanpa batas', NULL, NULL, '2026-09-23 01:00:02', NULL, '2026-09-23 00:58:07', '2026-09-23 01:00:02'),
(26, 6, 1269, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/6', 'kesalahan rani adalah menggunakan laptop di kasur yang membuat badan pegal, lampu kamar yg dimatikan membuat mata perih, tanpa mouse, tidak duduk di kursi, bekerja terlalu lama, dan layar tidak sejajar mata membuat pusing. \r\n\r\nbeli meja, mouse, kursi, dan lampu yang terang', NULL, NULL, '2026-09-23 00:58:27', NULL, '2026-09-23 00:58:27', '2026-09-23 00:58:27'),
(27, 5, 1289, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/5', '1. menyimpan laptop di atas kasur sehingga posisi tubuh tidak stabil.\r\n2. tidak menggunakan mouse jadi pergelangan tidak stabil\r\n3.laptop sejajar dengan dada\r\n4.pemcahayaan kamar di matikan\r\n5.duduk dalam posisi yang sama terlalu lama\r\n6.terlalu lama menatap layar', NULL, NULL, '2026-09-23 00:59:21', NULL, '2026-09-23 00:59:21', '2026-09-23 00:59:21'),
(28, 6, 1263, NULL, NULL, 'https://lms.yasor-ms.my.id', 'Laptop di atas kasur sebaiknya gunakan meja/laptop \r\nTidak memakai mouse sebaiknya beli mouse. Dengan\r\nLayar sejajar dada naikkan layar hingga sejajar mata.\r\nPosisi duduk tidak tegak gunakan kursi dengan sandaran yang nyaman\r\nPencahayaan terlalu gelap gunakan lampu meja\r\nPosisi kerja terlalu lama lakukan istirahat dan peregangan tubuh setiap 30–60 menit.', NULL, NULL, '2026-09-23 00:59:36', NULL, '2026-09-23 00:59:36', '2026-09-23 00:59:36'),
(29, 6, 1272, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/6', '1.bekerja menggunakan laptop di atas kasur, sehingga posisi tubuh tidak stabil.\r\n2.bidak menggunakan mouse, sehingga tangan dapat cepat lelah.\r\n3.posisi layar sejajar dengan dada, seharusnya mendekati tinggi mata.\r\n4.lampu kamar dimatikan saat bekerja, menyebabkan mata lebih cepat lelah.\r\n5.posisi kerja kemungkinan membungkuk, karena laptop terlalu rendah.\r\n6.bekerja terlalu lama tanpa memperhatikan\r\n\r\nstand laptop: ±Rp100.000\r\nmouse ergonomis: ±Rp75.000\r\nkeyboard eksternal: ±Rp100.000\r\nlampu meja: ±Rp100.000\r\nbantalan/dukungan punggung: ±Rp75.000\r\nsisanya untuk kebutuhan kecil/penyesuaian posisi kerja: ±Rp50.000\r\ntotal: ±Rp500.000.', NULL, NULL, '2026-09-23 00:59:41', NULL, '2026-09-23 00:59:41', '2026-09-23 00:59:41'),
(30, 5, 1294, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/5', 'Kasus Rani - FE Dev, kerja di kasur\r\n\r\n6 Kesalahan Ergonomis:\r\n1.  Kerja di kasur - punggung tidak ada support, bungkuk\r\n2.  Tanpa meja - laptop di atas kasur, sirkulasi panas tertutup\r\n3.  Layar sejajar dada / terlalu rendah - leher harus nunduk = sakit leher\r\n4.  Tanpa mouse - pergelangan menekuk terus, pegal\r\n5.  Lampu mati - kontras layar terang vs gelap = mata perih\r\n6.  No break & main HP/laptop sampai malam - mata lelah + blue light = sulit tidur\r\n\r\nPerbaikan Budget 500rb:\r\n- Meja lipat laptop (120rb) - biar tidak di kasur\r\n- Stand laptop / tumpukan buku (65rb / gratis) - angkat layar setinggi mata\r\n- Mouse wireless (75rb) + Keyboard murah (80rb)\r\n- Lampu meja LED (90rb) - wajib nyala saat kerja\r\n- Bantal punggung (70rb)\r\n\r\nTotal: ∼400rb\r\n\r\nAturan gratis: 20-20-20 tiap 20 menit lihat jauh 20 detik, Pomodoro 50-10 menit stretching, dan stop layar 1 jam sebelum tidur.', NULL, NULL, '2026-09-23 00:59:51', NULL, '2026-09-23 00:59:51', '2026-09-23 00:59:51'),
(31, 6, 1261, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/6', 'angaran 500 ribu 6 kesalahan nya bekerja di atas kasur\r\nkurangnya jeda istirahat\r\nposisi layar sejajar dada\r\ntidak memakai mouse\r\nmematikan lampu\r\npaparan cahaya berlebihan\r\n\r\nperbaikan menggunakan 500 ribu\r\nmembeli kursi dan meja 250 di ikea\r\nmembeli mouse 35 ribu di shopee\r\nmembenarkan waktu istirahat\r\nlampu belajar 50 ribu di shopee', NULL, NULL, '2026-09-23 01:00:31', NULL, '2026-09-23 01:00:31', '2026-09-23 01:00:31'),
(32, 6, 1277, NULL, NULL, 'http://lms.yasor-ms.my.id/lms/siswa/tugas/6', 'Kesalahan ergonomi:\r\n1.Laptop di atas kasur\r\n2.Layar tidak sejajar mata\r\n3.Tidak memakai mouse\r\n4.Pencahayaan terlalu gelap\r\n5.Posisi duduk tidak baik\r\n6.Kurang istirahat\r\nPerbaikan: Laptop stand, mouse, lampu meja, dan penyangga punggung. Total Rp450.000.', NULL, NULL, '2026-09-23 01:00:34', NULL, '2026-09-23 01:00:34', '2026-09-23 01:00:34'),
(33, 6, 1251, NULL, NULL, 'https://lms.yasor-ms.my.id/lms', '*Salah:* di kasur, layar rendah, tanpa mouse, lampu mati, no jeda, begadang.\r\n\r\n*Fix 500k:* Meja lipat 150k, mouse 100k, lampu 120k, stand 70k, bantal 50k. Layar sejajar mata, nyala lampu, 20 menit istirahat.', NULL, NULL, '2026-09-23 01:01:24', NULL, '2026-09-23 01:01:22', '2026-09-23 01:01:24'),
(34, 5, 1282, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/5', 'kesalahan Rani: \r\n- bekerja di kasur membuat badan jadi pegal dan bungkuk\r\n- ga pake mouse tangan jadi pegal\r\n- layar sejajar dengan dada jadi kepala kebanyakan nunduk yg menimbulkan sakit leher\r\n- lampu kamar dimatikan sehingga tidak ada pencahayaan yang membuat sakit mata\r\n\r\nrancangan anggaran:\r\n- meja laptop : 200.000\r\n- stand laptop : 60.000\r\n- mouse wireless : 100.000\r\n- lampu : 70.000\r\n- bantal sandaran : 50.000\r\ntotal kurleb 480.000', NULL, NULL, '2026-09-23 01:01:33', NULL, '2026-09-23 01:01:33', '2026-09-23 01:01:33'),
(35, 5, 1286, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/5', '- bekerja dengan laptop diatas kasur\r\n- tanpa menggunakan mouse\r\n- layar sejajar dengan dada \r\n- lampu kamar dimatikan \r\n- bekerja tanpa istirahat yang cukup\r\n- tidak ada pencahayaan saat mengerjakan pekerjaan \r\n\r\nanggaran:\r\n- meja laptop Rp.220.000\r\n- mouse Rp.130.000\r\n- lampu meja belajar Rp.110.000\r\n- bantal leher Rp.40.000', NULL, NULL, '2026-09-23 01:01:35', NULL, '2026-09-23 01:01:35', '2026-09-23 01:01:35'),
(36, 6, 1276, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/6', '1.  *Kerja di kasur:* Bikin punggung bungkuk, sakit leher.\r\n2.  *Layar sejajar dada:* Harusnya sejajar mata, jadi harus nunduk terus.\r\n3.  *Tanpa mouse:* Pergelangan ketekuk, risiko CTS.\r\n4.  *Lampu dimatikan:* Kontras layar terang vs ruangan gelap = mata perih.\r\n5.  *Blue light malam:* Tekan hormon tidur, makanya susah tidur.\r\n6.  *Gak ada istirahat:* Duduk statis berjam-jam tanpa stretching.\r\n\r\n*Solusi Budget 500rb:*\r\n- Meja lipat: 120rb - biar gak di kasur\r\n- Laptop stand (tumpukan buku): 75rb - angkat layar sejajar mata\r\n- Mouse wireless: 80rb\r\n- Keyboard kabel: 100rb\r\n- Lampu meja LED: 110rb - jangan kerja gelap-gelapan\r\n\r\n*Total: ±385rb*\r\n\r\n*Gratis:* Terapkan 20-20-20, aktifkan Night Light, dan Pomodoro 50-10 menit.', NULL, NULL, '2026-09-23 01:02:02', NULL, '2026-09-23 01:01:55', '2026-09-23 01:02:02'),
(37, 6, 1265, NULL, NULL, 'http://lms.yasor-ms.my.id/lms/siswa/tugas/6', '1.laptop digunakan di atas kasur posisi kerja tidak stabil\r\n2.tidak menggunakan mouse tangan pergelangan bisa cepat lelah\r\n3.layar terlalu rendah menyebabkan leher menunduk.\r\n4.tidak menggunakan kursi yang ergonomis dapat menyebabkan sakit punggung\r\n5.lampu kamar dimatikan membuat mata cepat lelah perih\r\n6.bekerja terlalu lama tanpa istirahat menyebabkan tubuh dan mata kelelahan\r\n\r\nlaptop stand: rp100.000\r\nmouse: rp50.000\r\nmampu meja: rp75.000\r\npenyangga punggung: rp100.000\r\nmeja sederhana: rp175.000\r\ntotal: rp500.000', NULL, NULL, '2026-09-23 01:01:59', NULL, '2026-09-23 01:01:59', '2026-09-23 01:01:59'),
(38, 5, 1293, NULL, NULL, 'http://lms.yasor-ms.my.id/lms/siswa/tugas/5', 'Kesalahan Rani:Di atas kasur: Punggung membungkuk karena alas tidak stabil.Layar sejajar dada: Kepala menunduk berlebihan, leher sakit.Tanpa mouse: Pakai trackpad bikin pergelangan tangan tegang.Lampu mati: Kontras layar vs kamar gelap bikin mata perih.Kurang jeda: Kerja terus-menerus memicu lelah fisik.Kerja di tempat tidur: Mengacaukan sleep hygiene, memicu sulit tidur.Rancangan Perbaikan (Anggaran < Rp500.000):Meja Lipat Lesehan: Rp100.000 (Menstabilkan laptop)Laptop Stand: Rp50.000 (Menaikkan layar ke arah mata)Mouse & Keyboard Wireless: Rp150.000 (Menjaga posisi tangan netral)Lampu Meja LED: Rp50.000 (Pencahayaan seimbang agar mata tidak perih)Bantal Sandaran Pinggang: Rp60.000 (Menopang tulang belakang)Total: ± Rp410.000', NULL, NULL, '2026-09-23 01:02:02', NULL, '2026-09-23 01:02:02', '2026-09-23 01:02:02'),
(39, 5, 1296, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/5', '1. menyimpan laptop di atas kasur kerja jadi tidak stabil 2\r\n2. tidak menggunakan mouse pergelangan akan lelah \r\n3. layar laptop terlalu bawah atau rendah\r\n4. pencahayaan yang kurang \r\n5. kerja tidak menggunakan meja dan kursi \r\n6. tidak memperhatikan waktu istirahat', NULL, NULL, '2026-09-23 01:02:37', NULL, '2026-09-23 01:02:22', '2026-09-23 01:02:37'),
(40, 5, 1287, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/5', 'Rani kurang memperhatikan posisi saat bekerja, seperti bekerja di kasur, layar laptop terlalu rendah, dan kamar terlalu gelap. Akibatnya, leher dan matanya menjadi sakit. Perbaikannya adalah menggunakan meja dan kursi yang nyaman, stand laptop, mouse, keyboard, dan lampu meja. Total biayanya sekitar Rp400.000, jadi masih di bawah anggaran Rp500.000.', NULL, NULL, '2026-09-23 01:02:58', NULL, '2026-09-23 01:02:58', '2026-09-23 01:02:58'),
(41, 6, 1252, NULL, NULL, 'https://lms.yasor-ms.my.id', 'Kesalahan Rani:\r\nLaptop dipakai di atas kasur.\r\nTidak menggunakan mouse.\r\nLayar laptop terlalu rendah sehingga leher menunduk.\r\nBekerja di kamar yang gelap.\r\nDuduk terlalu lama tanpa istirahat.\r\nJarang melakukan peregangan.\r\nTerlalu lama melihat layar sehingga mata perih.\r\nMenggunakan laptop sampai mengganggu waktu tidur.\r\nPerbaikan dengan budget Rp500.000:\r\nStand laptop: ±Rp100.000\r\nMouse: ±Rp70.000\r\nKeyboard: ±Rp100.000\r\nLampu meja: ±Rp80.000\r\nBantal duduk: ±Rp80.000', NULL, NULL, '2026-09-23 01:05:32', NULL, '2026-09-23 01:03:04', '2026-09-23 01:05:32'),
(42, 5, 1290, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/5', 'Kesalahan Ergonomis:\r\n\r\n1.  Kerja di atas kasur punggung gak ada penyangga, bikin pegal\r\n2.  Layar sejajar dada  harus nunduk terus, jadi sakit leher\r\n3.  Tanpa mouse pakai touchpad terus, pergelangan sakit\r\n4.  Lampu dimatikan layar jadi silau, mata perih\r\n5.  Gak pakai meja kursi posisi duduk bungkuk, tubuh cepat lelah\r\n6.  Gak ada istirahat + main laptop di kasur sampai malam - blue light bikin susah tidur\r\n\r\nSolusi Budget Rp 500.000:\r\n\r\n- Meja lipat laptop: Rp 120.000\r\n- Mouse wireless: Rp 85.000\r\n- Stand laptop: Rp 55.000\r\n- Lampu meja: Rp 95.000\r\n- Keyboard eksternal murah: Rp 80.000\r\n- Bantal punggung: Rp 60.000\r\nTotal: Rp 495.000', NULL, NULL, '2026-09-23 01:03:39', NULL, '2026-09-23 01:03:39', '2026-09-23 01:03:39'),
(43, 6, 1267, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/6', 'Kesalahannya rani bekerja di atas kasur\r\nPosisi layarnya sejajar dengan dada\r\nTidak memakai mouse\r\nMematikan lampu lamar\r\nKurang istirahat \r\nPaparan cahaya layar berlebih\r\n\r\nPerbaikan dengan 500 ribu\r\nMembeli meja lipat lesehan 125k\r\nMembeli dudukan laptop 100k\r\nMembeli mouse 35k\r\nMembeli bantal duduk 50k\r\nMembeli lampu belajar 20k', NULL, NULL, '2026-09-23 01:04:00', NULL, '2026-09-23 01:04:00', '2026-09-23 01:04:00'),
(44, 5, 1288, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/5', '**6 Kesalahan Ergonomis & Gaya Kerja:**\r\n\r\n1. Bekerja di atas kasur (posisi tubuh tidak stabil).\r\n\r\n\r\n2. Tanpa *mouse* (mengandalkan *trackpad*, pergelangan tegang).\r\n\r\n\r\n3. Layar sejajar dada (leher terus menunduk).\r\n\r\n\r\n4. Lampu kamar dimatikan (kontras cahaya tinggi, mata perih).\r\n\r\n\r\n5. Paparan *blue light* di tempat gelap (menghambat melatonin, pemicu insomnia).\r\n\r\n\r\n6. Bekerja di kasur (mencampur area kerja dan tidur).\r\n\r\n\r\n\r\n**Rancangan Perbaikan Cash (Anggaran Rp 500.000):**\r\n\r\n* Stand Laptop Adjustable: Rp 65.000\r\n\r\n\r\n* Keyboard External: Rp 75.000\r\n\r\n\r\n* Mouse Wireless: Rp 45.000\r\n\r\n\r\n* Lampu Meja LED: Rp 55.000\r\n\r\n\r\n* Meja Lesehan Laptop: Rp 110.000\r\n\r\n\r\n* Bantal Lumbar Support: Rp 45.000\r\n\r\n\r\n\r\n**Total Belanja:** Rp 395.000 (Sisa Rp 105.000 untuk ongkir/kacamata radiasi)', NULL, NULL, '2026-09-23 01:06:28', NULL, '2026-09-23 01:06:28', '2026-09-23 01:06:28'),
(45, 7, 1259, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/6', '1. Akar masalah beban kerja nya berlebihan dan terlalu bergantung pada satu orang tanpa back up\r\n2. Dokumentasi modul, prioritaskan bug, dan minta bantuan tim\r\n3. Bagis tugas, lakukan rotasi on call, code review, testing, datn tambah anggota yang memahami modul', NULL, NULL, '2026-09-23 01:17:39', NULL, '2026-09-23 01:17:39', '2026-09-23 01:17:39'),
(46, 7, 1280, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/7', '1. Akar masalah: Beban kerja Dimas terlalu berat dan sistem terlalu bergantung pada satu orang.\r\n\r\n\r\n2. Yang dilakukan Dimas: Sampaikan kondisi ke manager dan dokumentasikan ilmunya agar bisa dibagikan ke tim.\r\n\r\n\r\n3. Yang dilakukan tim & manager: Buat jadwal on-call bergilir, tambah orang yang memahami modul pembayaran, dan kurangi beban Dimas.', NULL, NULL, '2026-09-23 01:17:49', NULL, '2026-09-23 01:17:49', '2026-09-23 01:17:49'),
(47, 7, 1274, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/7', '1. Akar masalah: beban kerja terlalu berat, tidak ada rotasi on call yang sehat dan proses testing kurang baik sehingga sering terjadi bug.\r\n2. Yang bisa dilakukan Dimas: evaluasi prioritas tugas, komunikasi beban kerja, dokumentasikan bug.\r\n3. Tim&manajemen:terapkan sistem rotasi, OnCall, tambah sumber daya bila perlu.', NULL, NULL, '2026-09-23 01:18:14', NULL, '2026-09-23 01:17:58', '2026-09-23 01:18:14'),
(48, 7, 1253, NULL, NULL, 'https://lms.yasor-ms.my.id/lms', '1. Akar Masalah Sistematis:\r\n​Single Point of Failure: Dimas satu-satunya yang paham modul pembayaran.\r\n​Tidak Ada Rotasi: Siaga 24/7 tanpa shift memicu burnout dan penurunan kinerja.\r\n​Minim Dokumentasi: Pengetahuan sistem tidak tersebar ke tim.\r\n​2. Tindakan Dimas:\r\n​Komunikasi: Lapor kondisi burnout dan batas kemampuan ke atasan.\r\n​Dokumentasi: Buat panduan dasar modul pembayaran untuk tim.\r\n​Negosiasi: Minta jadwal on-call bergilir agar punya waktu istirahat.\r\n​3. Tindakan Tim & Manager:\r\n​Manager: Bebaskan Dimas dari piket malam sementara, buat jadwal on-call resmi bergiliran, dan beri ruang pemulihan.\r\n​Tim: Lakukan knowledge sharing (pairing session) dan bantu code review untuk mencegah bug sepele.', NULL, NULL, '2026-09-23 01:18:48', NULL, '2026-09-23 01:18:48', '2026-09-23 01:18:48'),
(49, 7, 1268, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/6', '1.Akar masalahnya Dimas menjadi satu satunya orang yang memahami modul pembayaran, \r\n\r\n2.Dimas perlu membuat dokumentasi dan mengajarkan modul tersebut kepada anggota tim lain, \r\n\r\n3.Tim dan manajer perlu membagi tugas dan pengetahuan agar tidak bergantung pada satu orang', NULL, NULL, '2026-09-23 01:18:53', NULL, '2026-09-23 01:18:53', '2026-09-23 01:18:53'),
(50, 7, 1260, NULL, NULL, 'https://lms.yasor-ms.my.id', '1. Akar masalah:\r\nCuma Dimas yang paham modul pembayaran, dan dia siaga 24/7 tanpa gantian selama 4 bulan. Wajar dia keteteran — ini soal desain kerja yang buruk, bukan salah Dimas.\r\n2. Yang bisa dilakukan Dimas:\r\nNgomong ke manager kalau bebannya kebanyakan\r\nTulis dokumentasi biar bukan cuma dia yang paham modul itu\r\nMinta di-review dulu sebelum PR di-submit\r\nAmbil istirahat kalau bisa\r\n3. Yang harus dilakukan tim/manager:\r\nBikin jadwal piket on-call gantian, jangan satu orang terus\r\nLatih orang lain juga paham modul pembayaran\r\nCari tahu kenapa insidennya sering banget (11x dalam 4 bulan) — mungkin ada masalah di sistemnya, bukan cuma manusianya\r\nCek kondisi Dimas secara rutin, jangan nunggu sampai kerjanya berantakan baru peduli', NULL, NULL, '2026-09-23 01:19:41', NULL, '2026-09-23 01:19:40', '2026-09-23 01:19:41'),
(51, 7, 1263, NULL, NULL, 'https://lms.yasor-ms.my.id', 'Akar masalah Perusahaan terlalu bergantung pada Dimas, kurang dokumentasi, pembagian tugas tidak merata,proses code review belum cukup optimal\r\nYang bisa dilakukan Dimas Menyampaikan kondisinya kepada atasan, membagi pengetahuan dengan tim, membuat dokumentasi, dan lebih harus teliti saat membuat pull request.\r\nYang harus dilakukan tim dan manajemen Membagi tugas, membuat dokumentasi, melakukan code review, mengurangi ketergantungan pada satu orang, serta memperbaiki sistem penanganan bug dan beban kerja', NULL, NULL, '2026-09-23 01:19:42', NULL, '2026-09-23 01:19:42', '2026-09-23 01:19:42'),
(52, 7, 1264, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/6', '1.ia terlalu siaga 24/7 tanpa rotasi sama sekali, dan selalu menangani 11 insiden di malam hari seorang diri\r\n2.Tetapkan jam mulai dan berhenti. Matikan notifikasi kerja di luar jam kerja. Tidur cukup (umumnya 7-9 jam untuk dewasa). Olahraga dan hobi non-layar. Pisahkan ruang kerja dan ruang istirahat. Ambil cuti sebelum kelelahan parah\r\n3.Batasi pekerjaan yang berjalan bersamaan (WIP limit). Rotasi tugas on-call. Gunakan retrospektif untuk membahas beban kerja. Hindari budaya \"pahlawan\" yang memuji orang yang lembur.', NULL, NULL, '2026-09-23 01:20:18', NULL, '2026-09-23 01:20:18', '2026-09-23 01:20:18'),
(53, 7, 1258, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/6', '1. Akar Maslaah sistematiknya itu ada di Dimas, dia allin all-out buat tugas orang lain , karena dia jago, sampe dia burn out sendiri karena ga ngebagi tugas secara sesuai.\r\n\r\n2. Dekomposisi dan Algoritma, bisa dengan pake skala prioritas, kerjain dari yg paling memungkinkan dulu, dan kerjakan dari yg deadline-nya paling Deket dulu, dan harus komunikasi sama tim biar dia ga kerjain semuanya sendiri \r\n\r\n3. Tim dan manager harus bisa inisiatif untuk belajar dan berkomunikasi dengan Dimas, supaya kerja tim dapat sesuai dengan seharusnya, biar kalo amit\' ada kendala pada Dimas atau bahkan Dimas resign, perusahaan ga bingung dan tetep bisa jalan', NULL, NULL, '2026-09-23 01:20:31', NULL, '2026-09-23 01:20:27', '2026-09-23 01:20:31'),
(54, 7, 1262, NULL, NULL, 'https://lms.yasor-ms.my.id/lms', '1.Masalahnya: Semua numpuk di Dimas doang. Gak ada yang backup, siaga terus, ya burnout.\r\n\r\n2.dimas Jangan ditahan sendiri. Tulis dokumentasi, ngomong ke manajer minta rotasi\r\n\r\n3. Tim dan bos Bikin jadwal jaga gantian, belajar bareng modul bayar itu, jangan biarin 1 orang yang ngerti', NULL, NULL, '2026-09-23 01:21:17', NULL, '2026-09-23 01:21:13', '2026-09-23 01:21:17'),
(55, 7, 1272, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/7', '1. akar masalah: beban kerja berlebihan dan hanya dimas yang memahami modul pembayaran, tanpa rotasi.\r\n2. yang dilakukan dimas: melapor kepada atasan, meminta bantuan, membuat dokumentasi, dan memperbaiki bug berdasarkan prioritas.\r\n3. tim dan manajemen: membuat sistem rotasi, membagi tugas, menambah anggota yang memahami modul, serta melakukan testing dan perbaikan sistem.', NULL, NULL, '2026-09-23 01:21:32', NULL, '2026-09-23 01:21:32', '2026-09-23 01:21:32'),
(56, 7, 1261, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/7', '1 akar masalah sangat ketergantungan kepada dimas tidak ada rotasi kerja\r\n2solusi untuk dimas komunikasi dengan hrd atau manager untuk cuti dan mengobrolkan masalah nya\r\n3memberikan dimas cuti dan rotasi kerja', NULL, NULL, '2026-09-23 01:22:04', NULL, '2026-09-23 01:22:04', '2026-09-23 01:22:04'),
(57, 7, 1267, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/7', '1. Tim terlalu bergantung kepada Dimas secara berlebih lalu menyebabkan burnout kepada Dimas \r\n2. Mengolah emosi dan stress lalu berkomunikasi dengan tim dan manager\r\n3. Mengurangi pekerjaan dimas agar tidak terjadi burnout lagi dan membagi tugas ke yang lain', NULL, NULL, '2026-09-23 01:22:31', NULL, '2026-09-23 01:22:31', '2026-09-23 01:22:31'),
(58, 7, 1254, NULL, NULL, 'https://lms.yasor-ms.my.id/lms', '1.akar masalah:Dimas terlalu sering kerja malam karena sistem kerja 24/7 tanpa rotasi,sehingga mengalami kelelahan dan performanya menurun\r\n2.yang bisa di lakukan dimas:atur waktu kerja dan istirahat sampaikan kondisi ke atasan dan jangan terus mengambil shift malem tanpa jeda \r\n3.yang harus dilakukan tim dan manager:buat sistem rotasi kerja/on call bagi tugas devara marata,evaluasi jumlah insidenn dan perbaiki SOP supaya beban dimas gak berlebihan', NULL, NULL, '2026-09-23 01:22:40', NULL, '2026-09-23 01:22:40', '2026-09-23 01:22:40'),
(59, 7, 1276, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/6', '*Akar masalahnya* sistem Single Point of Failure. Cuma Dimas yang paham pembayaran dan disuruh jaga dua puluh empat jam tanpa rotasi, makanya dia kelelahan, telat, emosian, dan PR banyak bug.\r\n\r\n*Dimas harus* stop jadi pahlawan, mulai dokumentasiin ilmunya pelan-pelan dan minta jadwal on-call yang jelas ke manager.\r\n\r\n*Tim & manager harus* bikin orang kedua yang paham lewat knowledge sharing, buat rotasi jaga malam plus kompensasi, dan kasih Dimas waktu istirahat.', NULL, NULL, '2026-09-23 01:42:22', NULL, '2026-09-23 01:22:45', '2026-09-23 01:42:22'),
(60, 7, 1255, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/7', 'Akar permasalahan tidak melakukan kebijakan on-call. Tanpa ada nya rotasi shift menjadikan Dimas burnout. \r\n2. First of all dia harus nya melakukan komunikasi terbuka, dengan mengajukan pergantian shift. Lalu dia juga harus menerapkan batasan waktu kerja. Dan jika sudah mulai lelah bisa mengajukan cuti untuk istirahat. \r\n3. Pertama manajernya harus memperbaiki jadwal kerja. Dimana seluruh BE ikut serta dalam siaga malam secara bergantian. Lalu tim juga seharus nya lebih memperhatikan kondisi dimas dan melakukan inisiatif dengan berkomunikasi.', NULL, NULL, '2026-09-23 01:23:02', NULL, '2026-09-23 01:22:58', '2026-09-23 01:23:02'),
(61, 7, 1277, NULL, NULL, 'http://lms.yasor-ms.my.id/lms/siswa/tugas/7', '1.Akar masalah: Beban kerja terlalu berat, kurang istirahat, dan sistem kerja tidak seimbang\r\n2.Yang dilakukan Dimas: Bicara dengan atasan, mengatur waktu kerja, dan meminta bantuan tim\r\n3.Tim & manajer: Membagi tugas, memperbaiki bug, menambah anggota jika perlu, serta mengatur jam kerja dan istirahat', NULL, NULL, '2026-09-23 01:23:03', NULL, '2026-09-23 01:23:03', '2026-09-23 01:23:03'),
(62, 8, 1291, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/5', '1. Akar masalah: Beban kerja berlebihan, kurang istirahat, dan kurangnya sistem kerja serta review kode.\r\n2. Yang bisa dilakukan Dimas: Mengatur waktu, beristirahat, membagi tugas, dan meningkatkan ketelitian saat coding.\r\n3. Tindakan tim dan manajer: Membagi beban kerja secara adil, menambah anggota atau backup, menerapkan code review, dan membuat jadwal kerja yang sehat.', NULL, NULL, '2026-09-23 01:23:19', NULL, '2026-09-23 01:23:15', '2026-09-23 01:23:19'),
(63, 7, 1257, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/7', '1. hanya dimas yang paham tentang modul pembayaran, jadi orang orang bergantung kepada dimas\r\n2.mengajarkan sistem ke anggota lain, mencari solusi nya, membuat panduan cara caranya agar tidak bergantung kepada dimas\r\n3.membagi pengetahuan, code review, \r\nmngajari orang agar paham tentang modul pembayaran', NULL, NULL, '2026-09-23 01:23:49', NULL, '2026-09-23 01:23:49', '2026-09-23 01:23:49'),
(64, 8, 1284, NULL, NULL, 'https://lms.yasor-ms.my.id/', '1. Akar masalah: Beban kerja berlebihan, kurang istirahat, dan kurangnya sistem kerja serta review kode.\r\n2. Yang bisa dilakukan Dimas: Mengatur waktu, beristirahat, membagi tugas, dan meningkatkan ketelitian saat coding.\r\n3. Tindakan tim dan manajer: Membagi beban kerja secara adil, menambah anggota atau backup, menerapkan code review, dan membuat jadwal kerja yang sehat.', NULL, NULL, '2026-09-23 01:24:01', NULL, '2026-09-23 01:23:59', '2026-09-23 01:24:01'),
(65, 7, 1251, NULL, NULL, 'https://lms.yasor-ms.my.id/lms', '1 Akar: Bus factor 1 + on-call 2 2 4/7 = burnout.\r\n2 Dimas:Dokumentasi + minta rotasi + istirahat.\r\n3 Tim/Manager:Buat rotasi dan sharing', NULL, NULL, '2026-09-23 01:24:10', NULL, '2026-09-23 01:24:10', '2026-09-23 01:24:10'),
(66, 7, 1265, NULL, NULL, 'http://lms.yasor-ms.my.id/lms/siswa/tugas/6', '- ketergantungan pada dimas dan beban kerja berlebih\r\n- membuat dokumentasi berbagi pengetahuan dengan tim dan memperbaiki bug secara bertahap\r\n- tim melakukan code review dan saling berbagi pengetahuan manajer membuat rotasi tugas pembagian kerja yang jelas dan memastikan tidak ada ketergantungan pada satu orang', NULL, NULL, '2026-09-23 01:24:24', NULL, '2026-09-23 01:24:24', '2026-09-23 01:24:24'),
(67, 7, 1269, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/6', '1. akar masalah yg dialami Dimas adalah hanya Dimas satu satunya yang faham modul tsb dan diperparah dengan dia yang harus siaga 24/7 tanpa rotasi dan menangani 11 insiden malam dalam 4 bulan. Situasi ini menjurus ke burnout\r\n2. memulai knowledge sharing agar tim dapat mempelajari dan memahami modul tsb agar Dimas tidak bekerja sendiri.\r\n3. memberikan Dimas nafas (istirahat) dan membantu Dimas mengatasi masalah masalah yang dialami, dan jangan membebankan semua pekerjaan ke Dimas', NULL, NULL, '2026-09-23 01:25:04', NULL, '2026-09-23 01:24:53', '2026-09-23 01:25:04'),
(68, 7, 1278, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/6', '1. akar masalah sistemik nya adalah beban kerja terlalu berat, tidak ada rotasi, dan kurangnya pembagian tugas.\r\n2. yang bisa dilakukan dimas adalah membuat dokumentasi modul, memperbaiki bug kecil, dan mengatur prioritas pekerjaan.\r\n3. yang harus dilakukan tim dan manajemen adalah tambah anggota, buat jadwal piket dan perbaiki pembagian beban kerja.', NULL, NULL, '2026-09-23 01:24:53', NULL, '2026-09-23 01:24:53', '2026-09-23 01:24:53'),
(69, 7, 1273, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/6', '1. akar masalahnya dimas bekeerja ekstrem sehingga burnout mengakibatman mudah marah dan penurunan kinerja bekerja.\r\n\r\n2. memulai knowledge sharing agar tim juga dapat mempelajari atau memahami modul pembayaran.\r\n\r\n3. memberikan dimas istirahat  untuk memulihkan burnout dan latih tim lain agar dapat memahami modul pembayaran juga dan tidak terbeban pasa satu org', NULL, NULL, '2026-09-23 01:24:56', NULL, '2026-09-23 01:24:53', '2026-09-23 01:24:56'),
(70, 7, 1266, NULL, NULL, 'https://ceunahh.com', '1. Akar masalah \r\nDimas jadi single point of failure — cuma dia yang paham modul pembayaran. Ditambah tidak ada rotasi/On call dan Dimas jadi siaga 24/7 tanpa jeda 4 bulan. Dan ia menjadi sulit tidur atau jam tidurnya menjadi rusak, picu telat, mudah kesal, bug sepele. \r\n2. Yang harus dimas lakukan\r\nSampaikan data konkret ke manager\r\nMinta jeda on-call sementara\r\nMulai dokumentasikan modul pembayaran biar gak nanggung sendirian\r\nJaga tidur di malam tanpa insiden\r\n3. Yang harus tim dan manager lakukan \r\nBuat rotasi on-call, cross-train minimal 1-2 orang lain\r\nAudit akar penyebab 11 insiden itu\r\nKasih Dimas waktu recovery eksplisit\r\nEvaluasi performa dengan konteks beban kerja, jangan asal nilai PR/telat', NULL, NULL, '2026-09-23 01:25:29', NULL, '2026-09-23 01:25:13', '2026-09-23 01:25:29'),
(71, 8, 1285, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/8', 'masalah sistematik nya adalah ketergantungan pada satu orang, beban kerja yang berlebihan, tidak ada rotasi, dan proses testing kurang baik\r\n\r\nyang bisa di lakukan dimas adalah menyampaikan beban kerja ke atasan, membuat dokumentasi modul, berbagi dengan anggota tim dan memperbaiki pola istirahat dan tidak selalu mengambil tugas sendiri\r\n\r\nyang harus di lakukan tim dan manajer menambah back up developer, memperbaiki code testing, mengatur beban kerja', NULL, NULL, '2026-09-23 01:25:51', NULL, '2026-09-23 01:25:51', '2026-09-23 01:25:51'),
(72, 8, 1283, NULL, NULL, 'https://lms.yasor-ms.my.id/', '1. Akar masalah: Beban kerja Dimas terlalu berat dan hanya bergantung pada satu orang.\r\n\r\n\r\n2. Dimas: Sampaikan kondisi ke atasan dokumentasikan sistem dan minta pembagian tugas.\r\n\r\n\r\n3. Tim/manager: Buat rotasi on-call tambah backup engineer  dan lakukan knowledge sharing.', NULL, NULL, '2026-09-23 01:27:55', NULL, '2026-09-23 01:27:49', '2026-09-23 01:27:55'),
(73, 8, 1287, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/8', 'Akar masalah: Beban kerja Dimas terlalu berat karena hanya dia yang menguasai modul pembayaran dan tidak ada pembagian tugas/rotasi\r\nYang harus dilakukan Dimas: Sampaikan kondisinya ke atasan, minta pembagian tugas, dan jangan terus memaksakan diri bekerja 24/7\r\nYang harus dilakukan tim & manajer: Buat sistem backup dan rotasi, dokumentasikan pengetahuan Dimas, serta atur beban kerja agar tidak menumpuk pada satu orang', NULL, NULL, '2026-09-23 01:27:59', NULL, '2026-09-23 01:28:00', '2026-09-23 01:28:00'),
(74, 7, 1252, NULL, NULL, 'https://lms.yasor-ms.my.id', '1. Akar masalah: Beban kerja Dimas berlebihan karena hanya dia yang menguasai modul pembayaran dan tidak ada rotasi on-call.\r\n\r\n\r\n2. yang harus dilakukan dimas: Sampaikan masalah ke atasan, buat dokumentasi, berbagi pengetahuan, dan mengatur waktu istirahat.\r\n\r\n\r\n3. yang harus dilakukan tim dan manager : Buat rotasi on-call, tambah backup engineer, lakukan knowledge sharing, dokumentasi, dan perbaiki proses testing/review.', NULL, NULL, '2026-09-23 01:28:04', NULL, '2026-09-23 01:28:04', '2026-09-23 01:28:04'),
(75, 8, 1289, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/8', '1. beban kerja dimas terlalu berlebihan dan dimas tidak ada waktu untuk beristirahat \r\n2. mengatur jam istirahat dimas, mengurangi waktu siaga 24/7, dan mengkomunikasikan beban kerja kepada atasan\r\n3. membagi tanggung jawab secara merata, membuat sistem piket bergantian, danmemastikan dimas mendapatkan waktu istirahat', NULL, NULL, '2026-09-23 01:28:05', NULL, '2026-09-23 01:28:05', '2026-09-23 01:28:05'),
(76, 7, 1275, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/7', '1.  Akar Masalah:\r\n- Bus Factor = 1 - Cuma Dimas yang paham modul pembayaran (Single Point of Failure)\r\n- Tanpa rotasi on-call 24/7- 11 insiden malam = kurang tidur = burnout\r\n- Tidak ada dokumentasi & monitoring\r\n\r\n2. Dimas harus:\r\n- Komunikasi ke manager minta rotasi & bantuan\r\n- Bikin dokumentasi modul pembayaran\r\n- Istirahat, jaga kesehatan (K3)\r\n\r\n3. Tim & Manager harus:\r\n- Crocs-training - minimal 2 orang paham 1 modul kritis\r\n- Buat rotasi jaga malam+ kompensasi\r\n- Perbaiki code review- bimbing, bukan menghakimi\r\n- Terapkan DevOps & dokumentasi wajib', NULL, NULL, '2026-09-23 01:28:12', NULL, '2026-09-23 01:28:12', '2026-09-23 01:28:12'),
(77, 8, 1296, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/8', '1. akar masalahnya yaitu : beban kerja dimas terlalu berat dan tidak ada pembagian tugas\r\n2. yang bisa dilakukan dimas : belajar modul lain dan mengatur waktu kerja.\r\n3. yang harus dilakukan tim/manager: membagi tugas dengan adil dan menambah anggota tim agar tidak stress', NULL, NULL, '2026-09-23 01:28:21', NULL, '2026-09-23 01:28:14', '2026-09-23 01:28:21'),
(78, 8, 1290, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/8', '1. Akar masalah sistematik:*l\r\n- Bus Factor = 1/ Single Point of Failure. Cuma Dimas yang ngerti, kalau dia tumbang sistem tumbang.\r\n- Tidak ada rotasi on-call & dokumentasi.\r\n- Beban kerja tidak manusiawi = burnout.\r\n\r\n2. Yang bisa Dimas lakukan:\r\n- Stop jadi pahlawan. Tulis dokumentasi / runbook cara handle insiden.\r\n- Ngomong ke manager: \"Gue butuh backup, gue udah burnout\".\r\n- Tidur yang bener, jangan cek HP terus, tolak lembur diluar jam.\r\n\r\n3. Yang harus Tim & Manager lakukan:\r\n- Bikin rotasi jaga malam. Jangan Dimas terus.\r\n- Knowledge sharing: Pair programming biar minimal 2 orang paham modul pembayaran.\r\n- Perbaiki estimasi: Pakai Hukum Hofstadter - kerjaan selalu lebih lama dari perkiraan, jadi tambah buffer 20-30% untuk deadline.\r\n- Bikin postmortem tiap insiden, bukan nyalahin orang.\r\n\r\nIntinya: Ini bukan salah Dimas malas, tapi sistemnya yang bikin dia kelelahan', NULL, NULL, '2026-09-23 01:28:16', NULL, '2026-09-23 01:28:16', '2026-09-23 01:28:16'),
(79, 7, 1279, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/7', 'Dimas kecapekan sendirian.\r\n\r\nAkar masalah:cuma dia yang ngerti, jaga malam terus tanpa gantian.\r\n\r\nDimas:ngomong ke bos minta gantian, bikin catatan biar tim lain ngerti.\r\n\r\nTim/Bos:jangan biarin 1 orang doang yang ngerti, bikin jadwal jaga gantian, jangan galak pas review code.', NULL, NULL, '2026-09-23 01:29:14', NULL, '2026-09-23 01:29:14', '2026-09-23 01:29:14'),
(80, 7, 1281, NULL, NULL, 'https://lms.yasor-ms.my.id', '1. Akar Masalah Sistematis:\r\n​Single Point of Failure: Dimas satu-satunya yang paham modul pembayaran.\r\n​Tidak Ada Rotasi: Siaga 24/7 tanpa shift memicu burnout dan penurunan kinerja.\r\n​Minim Dokumentasi: Pengetahuan sistem tidak tersebar ke tim.\r\n​2. Tindakan Dimas:\r\n​Komunikasi: Lapor kondisi burnout dan batas kemampuan ke atasan.\r\n​Dokumentasi: Buat panduan dasar modul pembayaran untuk tim.\r\n​Negosiasi: Minta jadwal on-call bergilir agar punya waktu istirahat.\r\n​3. Tindakan Tim & Manager:\r\n​Manager: Bebaskan Dimas dari piket malam sementara, buat jadwal on-call resmi bergiliran, dan beri ruang pemulihan.\r\n​Tim: Lakukan knowledge sharing (pairing session) dan bantu code review untuk mencegah bug sepele.', NULL, NULL, '2026-09-23 01:29:35', NULL, '2026-09-23 01:29:35', '2026-09-23 01:29:35'),
(81, 8, 1282, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/8', '1. akar masalahnya ada di : \r\n- manajemen yg jelek\r\n- karena cuma Dimas yg paham dgn modul pembayaran dan harus standby 24/7 tanpa rotasi\r\n2. yg bisa dilakukan Dimas :\r\n- berbicara jujur kepada manager kalau pekerjaannya sudah overload sehingga Dimas membutuhkan istirahat yg cukup \r\n- dan Dimas bisa mulai menyicil untuk membuat dokumentasi agar teman yg lain bisa membantu\r\n3. yg dilakukan tim dan manajer : \r\n- membuat jadwal rotasi dengan adil atau merata jadi tidak hanya Dimas yg mengerjakan\r\n- merekrut dev tambahan\r\n(tim)\r\n- mempelajari modul dgn Dimas langsung \r\n- membantu code review', NULL, NULL, '2026-09-23 01:30:07', NULL, '2026-09-23 01:30:07', '2026-09-23 01:30:07'),
(82, 8, 1286, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/8', 'akar masalah dimas:\r\n- dimas satu satunya yang paham modul pembayaran sedangkan beberapa insiden mulai bermunculan dan jika dimas resign/sakit perusahaan tidak bisa menghandle sepenuhnya tentang paham modul yang dimas ketahui sendiri sebagai BE\r\n- tidak ada batasan kerja dan istirahat yang kurang membuat ia jadi lebih sering masuk terlambat , mudah lelah \r\n\r\nyang bisa dilakukan dimas:\r\n- mencatat waktu kapan dia bekerja dan kapan dia beristirahat dengan cukup \r\n- dokumentasikan modul yang ia ketahui sendiri agar tim bisa mengaksesnya juga\r\n\r\nyang harus dilakukan tim & manager:\r\n- membagi tugas dengan lebih efisien agar tim bekerja dan tidak hanya dimas yang mengandalkannyA', NULL, NULL, '2026-09-23 01:30:47', NULL, '2026-09-23 01:30:47', '2026-09-23 01:30:47'),
(83, 8, 1288, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/8', '**1. Akar masalah:** Bus factor—satu orang (Dimas) pegang modul kritikal tanpa dokumentasi, tidak ada rotasi on-call yang adil, proses review lemah (bug sepele lolos), dan tanda burnout diabaikan.\r\n\r\n**2. Yang bisa dilakukan Dimas:**\r\n- Sampaikan beban kerja & kelelahan ke manager\r\n- Mulai dokumentasikan modul sedikit-sedikit\r\n- Minta pairing/review dari rekan lain\r\n- Ajukan rotasi on-call yang lebih adil\r\n\r\n**3. Yang harus dilakukan tim & manager:**\r\n- Buat rotasi on-call merata, bukan ke satu orang\r\n- Alokasikan waktu knowledge transfer & dokumentasi\r\n- Perbaiki proses review (checklist/linting) agar bug sepele tertangkap lebih awal\r\n- Manager pantau tanda burnout dan lakukan 1-on-1 lebih awal', NULL, NULL, '2026-09-23 01:31:06', NULL, '2026-09-23 01:30:57', '2026-09-23 01:31:06');
INSERT INTO `pengumpulan_tugas` (`id`, `tugas_id`, `siswa_id`, `tugas_kelompok_id`, `file_jawaban`, `link_jawaban`, `catatan_siswa`, `nilai`, `catatan_guru`, `dikumpulkan_at`, `dinilai_at`, `created_at`, `updated_at`) VALUES
(84, 8, 1294, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/8', '*Kasus Dimas - BE satu-satunya yg paham pembayaran, siaga 24/7, 11 insiden malam dalam 4 bulan.*\r\n\r\n*1. Akar masalah:* Bus Factor = 1, on-call tanpa rotasi = burnout, tidak ada dokumentasi & perbaikan permanen.\r\n\r\n*2. Dimas harus:* Stop jadi hero. Dokumentasikan modul, catat semua lembur/insiden sebagai data, dan minta rotasi ke manager.\r\n\r\n*3. Tim & Manager harus:*\r\n- Buat rotasi on-call + kompensasi\r\n- Pairing / knowledge sharing biar tidak cuma 1 orang yang bisa\r\n- Stop tambal sulam, bikin post-mortem dan perbaiki akar bug modul pembayaran', NULL, NULL, '2026-09-23 01:31:31', NULL, '2026-09-23 01:31:31', '2026-09-23 01:31:31'),
(85, 8, 1293, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/8', '1. Akar masalah sistematik:single point of failure, burnout ekstrem, manajemen risiko lemah\r\n2.Tindakan dimas:komunikasi terbuka, buat dokumentasi, ajukan cuti\r\n3.Tindakan Tim manajer:Knowledge Sharing, rotasi on call, evaluasi insiden', NULL, NULL, '2026-09-23 01:34:27', NULL, '2026-09-23 01:34:27', '2026-09-23 01:34:27'),
(86, 8, 1295, NULL, NULL, 'https://lms.yasor-ms.my.id/', 'Single Point of Failure Dimas menjadi satu-satunya orang yang paham modul pembayaran.   Tidak ada sistem rotasi & batas kerja: Harus siaga 24/7, memicu kelelahan ekstrem penurunan performa, dan rusaknya work-life balance\r\nyang bisa di lakukan dimas :\r\nKomunikasi jujur  kondisi burnout dan penurunan performanya ke manajer\r\nDokumentasi dan Knowledge Transfer  Membuat panduanmodul pembayaran agar anggota tim lain bisa mempelajari dan membantunya\r\n#yang harus di lakukan tim dan manager \r\nKomunikasi jujur Menyampaikan kondisi burnout dan penurunan performanya ke manajer\r\nDokumentasi dan Knowledge Transfer Membuat panduan modul pembayaran agar anggota tim lain bisa mempelajari dan membantunya', NULL, NULL, '2026-09-23 01:34:35', NULL, '2026-09-23 01:34:35', '2026-09-23 01:34:35'),
(87, 10, 1262, NULL, NULL, 'https://lms.yasor-ms.my.id/lms', '1. B. 50-70 cm\r\n2. B. Tiap 20 menit liat jauh 20 kaki / 6m selama 20 detik\r\n3. B. Stres kerja kronis yang gak kekelola\r\n4. C. Kasih tau awal + bawa fakta & opsi\r\n5. B. 5,5 hari- rumus (3+45+10)/6\r\nNih singkat:\r\n6. B - yang ada fakta Situasi, Perilaku, Dampak\r\n7.A\r\n8. B. Backup harus dites restore & kerja berisiko wajib SOP\r\n9. B. Simpan di env / secret managerjangan di repo/chat\r\n10. A. 3 salinan, 2 media beda, 1 di lokasi beda', NULL, NULL, '2026-09-23 01:45:31', NULL, '2026-09-23 01:42:12', '2026-09-23 01:45:31'),
(88, 9, 1291, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/5', '1.B. 50–70 cm\r\n2.B. Setiap 20 menit melihat objek sejauh sekitar 20 kaki selama 20 detik\r\n3.B. Fenomena okupasional akibat stres kerja kronis\r\n4.C. Memberi tahu lebih awal disertai fakta dan opsi\r\n5.B. 5,5 har\r\n6.B\r\n7.C\r\n8.B\r\n9.B\r\n10.A', NULL, NULL, '2026-09-23 01:45:01', NULL, '2026-09-23 01:42:21', '2026-09-23 01:45:01'),
(89, 9, 1284, NULL, NULL, 'https://lms.yasor-ms.my.id/', '1.B. 50–70 cm\r\n2.B. Setiap 20 menit melihat objek sejauh sekitar 20 kaki selama 20 detik\r\n3.B. Fenomena okupasional akibat stres kerja kronis\r\n4.C. Memberi tahu lebih awal disertai fakta dan opsi\r\n5.B. 5,5 hari\r\n6.  B\r\n7.  C\r\n8.  B\r\n9. B\r\n10. A', NULL, NULL, '2026-09-23 01:46:21', NULL, '2026-09-23 01:42:29', '2026-09-23 01:46:21'),
(90, 10, 1258, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/6', '1-B, 2-B, 3-B, 4-C, 5-B (E = (3 + 20 + 10)/6 = 5,5), 6-B, 7-C, 8-B, 9-B, 10-A.', NULL, NULL, '2026-09-23 01:43:50', NULL, '2026-09-23 01:43:36', '2026-09-23 01:43:50'),
(91, 9, 1289, NULL, NULL, 'https://lms.yasor-ms.my.id/lms/siswa/tugas/9', '1.B\r\n2.B\r\n3.B\r\n4.C\r\n5.B\r\n6.B\r\n7.C\r\n8.B\r\n9.B\r\n10.A', NULL, NULL, '2026-09-23 01:45:58', NULL, '2026-09-23 01:43:43', '2026-09-23 01:45:58'),
